  'Pro seat price': 'Pris per Pro-plats', 'per seat and month': 'per plats och månad', 'Price': 'Pris', 'Currency': 'Valuta', 'Save price': 'Spara pris', 'Test mode': 'Testläge', 'Live': 'Skarpt läge',
