/** Dates like "9 Nov", "9 Nov 2026", "Sunday 8 November" and month names inside any text. */
export function svDates(s: string) {
  return s
    .replace(/\b(\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b/g, (_, d, m) => `${d} ${MON[m]}`)
    .replace(/\b(Sunday|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday) (\d{1,2}) (January|February|March|April|May|June|July|August|September|October|November|December)\b/g, (_, w, d, m) => `${DAY[w]} ${d} ${MONTH[m]}`)
    .replace(/\b(\d{1,2}) (January|February|March|April|May|June|July|August|September|October|November|December)\b/g, (_, d, m) => `${d} ${MONTH[m]}`);
}
